import itertools

n = 19
fixed_seq = {4: -1, 12: 1, 13: -1}
fixed_c = {1: -1, 2: 0, 7: -3}

free_indices = [i for i in range(n) if i not in fixed_seq]

def compute_c(seq):
    c = {}
    for k in range(1, n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i+k]
        c[k] = s
    return c

satisfying_c = []
for bits in itertools.product([-1, 1], repeat=len(free_indices)):
    seq = [0]*n
    for idx, val in zip(free_indices, bits):
        seq[idx] = val
    for idx, val in fixed_seq.items():
        seq[idx] = val
    c = compute_c(seq)
    ok = True
    for k, val in fixed_c.items():
        if c[k] != val:
            ok = False
            break
    if ok:
        satisfying_c.append((seq[:], c))

print("sequences satisfying fixed c constraints:", len(satisfying_c))
if satisfying_c:
    min_sum_sq = float('inf')
    best = None
    for seq, c in satisfying_c:
        sum_sq = sum(c[k]**2 for k in range(1, n))
        if sum_sq < min_sum_sq:
            min_sum_sq = sum_sq
            best = (seq, sum_sq, c)
    print("min sum_sq:", min_sum_sq)
    print("best seq:", best[0])
    print("best c:", [best[2][k] for k in range(1, n)])

